let lang=localStorage.getItem('spqr-lang')==='zh'?'zh':'en';
const initialView=(centerId='cisalpine')=>{
 if(window.innerWidth>800)return [0,0,1200,650];
 const stageWidth=Math.max(200,window.innerWidth-(window.innerWidth<=700?42:58)),stageHeight=Math.max(360,window.innerHeight-54);
 const width=Math.max(200,Math.min(580,Math.round(650*stageWidth/stageHeight))),[center]=mapPoint(centerId);
 return [Math.max(0,Math.min(1200-width,center-width/2)),0,width,650];
};
let state=newGrandGame(),selectedRegion='cisalpine',selectedArmy='xiii',selectedBattle=null,reportFilters={},dismissedAlert=null,tab='map',devBranch='material',treeZoom=1,ordering=false,speed=1,playing=false,timer=null,toast='',chosenFaction='caesar',setupOpen=false,panelOpen=false,mapMode='political',view=initialView('cisalpine');
const received=receiveHandoff(sessionStorage,'campaign',upgradeSave);
let entryOpen=!received;
if(received){state=received;selectedRegion=state.regions.find(r=>r.owner===state.player)?.id||state.regions[0]?.id;selectedArmy=state.armies.find(a=>a.owner===state.player)?.id||null;chosenFaction=state.player}
const t=k=>ui[lang][k]; const n=a=>a?.[lang==='zh'?1:0]||'';
const labelFaction=id=>n(FACTIONS[id]?.short)||id;
const fmt=x=>Math.round(x).toLocaleString(lang==='zh'?'zh-CN':'en-US');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function flash(message){toast=message;render();setTimeout(()=>{if(toast===message){toast='';render()}},3200)}
function date(){return lang==='zh'?`公元${state.year<0?'前':'后'}${Math.abs(state.year)}年 ${state.month}月`:`${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][state.month-1]} ${Math.abs(state.year)} ${state.year<0?'BCE':'CE'}`}
function ownArmies(){return state.armies.filter(a=>a.owner===state.player)}
function status(a){return a.trainingRemaining?(lang==='zh'?'训练中':'Training'):a.move?`${t('marching')} → ${n(region(state,a.move.to).name)} (${a.move.remaining})`:a.siege?`${t('siege')} (${a.siege.remaining})`:t('available')}

function mapSvg(){const a=army(state,selectedArmy);return drawMap(state,{selectedRegion,selectedArmy,mode:mapMode,lang,view,reachable:ordering&&a?adjacent(a.region,state).map(x=>x.to):[],recentChanges:(state.campaignEvents||[]).filter(e=>e.type==='control'&&e.year===state.year&&e.month===state.month).map(e=>e.regionId)})}

function stat(k,value){return `<div class="stat"><small>${t(k)}</small><strong>${value}</strong></div>`}
function socialDetails(r){if(!state.grandMap)return '';const own=r.owner===state.player,faith=({['roman-cults']:['Roman civic cults','罗马城邦祭仪'],['hellenic-cults']:['Hellenic cults','希腊祭仪'],['egyptian-cults']:['Egyptian cults','埃及祭仪'],['local-cults']:['Local traditions','地方信仰']})[r.faiths?.[0]?.id]||['Local traditions','地方信仰'];return `<div><dt>${lang==='zh'?'人口':'Population'}</dt><dd>${own?fmt(r.population):lang==='zh'?'未调查':'Unsurveyed'}</dd></div><div><dt>${lang==='zh'?'主要信仰':'Main tradition'}</dt><dd>${faith[lang==='zh'?1:0]} · ${r.faiths?.[0]?.share||70}%</dd></div><div><dt>${lang==='zh'?'民众满意度':'Civic satisfaction'}</dt><dd>${own?`${r.civicSatisfaction}%`:lang==='zh'?'未知':'Unknown'}</dd></div><div><dt>${lang==='zh'?'融合度':'Integration'}</dt><dd>${own?`${r.integration}%`:lang==='zh'?'未知':'Unknown'}</dd></div>`}
function warOverview(){
 const opponents=(state.wars||[]).filter(pair=>pair.includes(state.player)).map(pair=>pair.find(id=>id!==state.player));
 const civil=['caesar','senate'].includes(state.player)&&opponents.includes(state.player==='caesar'?'senate':'caesar');
 const current=opponents.length?opponents.map(id=>labelFaction(id)).join(lang==='zh'?'、':', '):lang==='zh'?'无':'None';
 return `<div class="rule-block"><h3>${lang==='zh'?'当前战争':'ACTIVE WARS'}</h3><p>${lang==='zh'?'交战对象：':'Opponents: '}${esc(current)}${lang==='zh'?'。':'.'}</p>${civil?`<p>${t('warText')}</p>`:''}</div>`;
}
function mapLegendFactions(){return [...new Set([state.player,'caesar','senate'])].map(id=>[id,FACTIONS[id]])}
function panel(){
  const r=region(state,selectedRegion),a=visibleArmyForPlayer(state,state.player,selectedArmy);
  if(tab==='notifications')return `<div class="panel-heading"><h2>${reportLabel('notifications',lang)}</h2></div>${notificationsHtml(state,lang)}`;
  if(tab==='battle')return battleReportHtml(state,state.battles?.find(b=>b.id===selectedBattle),lang);
  if(tab==='development')return developmentPanel(state,lang,devBranch);
  if(tab==='ideas')return ideasPanel(state,lang);
  if(tab==='military')return `<div class="panel-heading"><span class="eyebrow">${['caesar','senate'].includes(state.player)?'LEGIONES':lang==='zh'?'野战部队':'FIELD FORCES'}</span><h2>${t('armies')}</h2></div><div class="army-list">${ownArmies().map(x=>`<button data-select-army="${x.id}" class="army-row ${selectedArmy===x.id?'on':''}"><span><b>${esc(n(x.name))}</b><small>${esc(n(region(state,x.region).name))} · ${esc(status(x))}</small></span><strong>${fmt(x.men)}</strong></button>`).join('')}</div><p class="hint">${t('instructions')}</p>`;
  if(tab==='government')return `<div class="panel-heading"><span class="eyebrow">${esc((state.world.leadership[state.player]||[]).map(id=>n(CHARACTER_CATALOG[id]?.name)).filter(Boolean).join(lang==='zh'?'、':', ')||(lang==='zh'?'暂缺':'Vacant'))}</span><h2>${labelFaction(state.player)} · ${t('government')}</h2></div>${warOverview()}<div class="rule-block"><h3>${t('diplomacy')}</h3><p>${t('diplomacyText')}</p>${PLAYABLE.filter(id=>id!==state.player&&state.regions.some(r=>r.owner===id)).map(id=>{const war=isWar(state,state.player,id),allied=isAllied(state,state.player,id),rel=relation(state,state.player,id),civil=['caesar','senate'].includes(state.player)&&id===(state.player==='caesar'?'senate':'caesar');return `<div class="diplomatic-country"><span class="identity-inline">${factionMark(id)}<b>${labelFaction(id)}</b></span> · ${t('relations')} ${rel} ${allied?' · '+t('allied'):''}${war?' · '+t('atWar'):''}<button class="action" data-dip="${id}" data-act="${war?(civil?'settlement':'peace'):'war'}" ${allied?'disabled':''}>${war?(civil?(lang==='zh'?'提出内战和议 · 4国库':'Propose civil settlement · 4¤'):t('peace')):t('declare')}</button><button class="action" data-dip="${id}" data-act="improve" ${war?'disabled':''}>${t('improve')}</button><button class="action" data-dip="${id}" data-act="${allied?'break':'alliance'}" ${!allied&&(rel<30||war)?'disabled':''}>${allied?t('breakAlliance'):t('ally')}</button></div>`}).join('')}</div>${state.world.governments?.[state.player]?.civilWarRecognition?`<div class="rule-block"><p>${state.world.governments[state.player].civilWarRecognition==='recognized'?(lang==='zh'?'内战和议已确认本方政府的政治地位。':'The civil settlement recognizes this government.'):(lang==='zh'?'本方已在内战和议中承认对方政府。':'This government conceded recognition in the civil settlement.')}</p></div>`:''}${budgetHtml(state,lang,warContributionPlan(state,state.player))}<div class="rule-block"><h3>${t('tax')}</h3><div class="segmented">${['low','normal','high'].map(level=>`<button data-tax="${level}" class="${state.factions[state.player].tax===level?'active':''}">${t(level)}</button>`).join('')}</div><p>${t('taxText')}</p></div><div class="rule-block"><h3>${t('revolt')}</h3><p>${t('revoltText')}</p></div>`;
  if(tab==='chronicle')return `<div class="panel-heading"><span class="eyebrow">ANNALES</span><h2>${reportLabel('chronicle',lang)}</h2></div>${briefingHtml(state,lang)}${chronicleHtml(state,lang,reportFilters)}`;
  if(tab==='sources')return `<div class="panel-heading"><span class="eyebrow">FONTES</span><h2>${t('sourceTitle')}</h2></div><p class="source-note">${t('sourceNote')}</p><div class="source-list">${SOURCES.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer"><span>${esc(s.title)}</span><small>${t('open')}</small></a>`).join('')}</div>`;
  return `<div class="panel-heading"><span class="eyebrow">PROVINCIA</span><h2>${r?t('selected'):t('select')}</h2></div>${r?`<div class="region-title"><div class="campaign-identity">${factionMark(r.owner,'banner')}</div><div><h3>${esc(n(r.name))}</h3><small>${esc(r.city)}</small></div></div><dl class="detail-list"><div><dt>${t('owner')}</dt><dd>${esc(labelFaction(r.owner))}</dd></div><div><dt>${t('terrain')}</dt><dd>${t('terrainNames')[r.terrain]}</dd></div><div><dt>${t('supply')}</dt><dd>${r.supply},000</dd></div><div><dt>${t('loyalty')}</dt><dd>${r.owner===state.player?r.loyalty+'%':(lang==='zh'?'未知':'Unknown')}</dd></div><div><dt>${t('fort')}</dt><dd>${fortificationText(state,state.player,r.id,lang)}</dd></div>${socialDetails(r)}</dl><button class="action" id="recruit">${t('recruit')}</button>`:''}<div class="separator"></div><span class="eyebrow">EXERCITVS</span><h3 class="section-title">${t('army')}</h3>${a?`<div class="selected-army"><span class="identity-inline">${factionMark(a.owner,'insignia')}<b>${esc(n(a.name))}</b></span>${a.owner===state.player?`<small>${esc(n(a.commander))}</small><small>${fmt(a.men)} ${t('men')} · ${a.morale} ${t('morale')}</small><small>${esc(status(a))}</small>`:`<small>${lang==='zh'?`上次报告：公元前${Math.abs(a.year)}年${a.month}月；当前位置、兵力和状态未知。`:`Last reported ${a.month}/${Math.abs(a.year)} BCE; current location, strength and status unknown.`}</small>${CHARACTER_CATALOG[a.commanderId]?`<small>${lang==='zh'?'上次报告的指挥官':'Reported commander'}: ${esc(n(CHARACTER_CATALOG[a.commanderId].name))} · ${lang==='zh'?'可能过时':'may be outdated'}</small>`:''}`}</div><button class="action primary" id="order" ${a.owner!==state.player||!!a.move||!!a.siege||!!a.trainingRemaining?'disabled':''}>${ordering?t('cancel'):t('order')}</button>${a.owner===state.player&&!a.move&&!a.siege&&!a.trainingRemaining&&region(state,a.region).owner===state.player&&a.experience<5?`<button class="action" id="train-army">${lang==='zh'?'野战训练 · 8国库/2粮/1月':'Field training · 8¤ / 2 food / 1 month'}</button>`:''}${ordering?`<p class="order-note">${t('target')}</p>`:''}`:`<p class="hint">${t('noArmy')}</p>`}`;
}

function requestMarch(destination){
 const plan=previewMarch(state,selectedArmy,destination);if(!plan.ok){flash(t('invalid'));return}
 const commit=()=>{const result=moveArmy(state,selectedArmy,destination);if(!result.ok){flash(t('invalid'));return}ordering=false;selectedRegion=destination;tab='map';panelOpen=true;render()};
 if(!plan.hostile){commit();return}
 const unit=army(state,selectedArmy),target=region(state,destination),overlay=document.createElement('div');overlay.className='march-review-overlay';overlay.innerHTML=`<div class="march-review" role="dialog" aria-modal="true" aria-label="${lang==='zh'?'战前情报':'Pre-battle intelligence'}">${intelligenceHtml(assessment(state,unit.id,destination,plan),target,lang)}<div class="march-review-actions"><button data-review="attack">${lang==='zh'?'仍要进攻':'ATTACK ANYWAY'}</button><button data-review="scouts">${lang==='zh'?'派斥候 · 4国库/2粮/1月':'SEND SCOUTS · 4¤ / 2 food / 1 month'}</button><button data-review="probe">${lang==='zh'?'试探敌阵 · 3粮/可能伤亡':'PROBE POSITIONS · 3 food / possible losses'}</button><button data-review="reinforce">${lang==='zh'?'请求增援 · 24国库/6粮/3000兵源/1月':'REQUEST REINFORCEMENTS · 24¤ / 6 food / 3,000 manpower / 1 month'}</button><button data-review="delay">${lang==='zh'?'延迟进攻 · 推进1月':'DELAY ATTACK · 1 month'}</button><button data-review="cancel">${lang==='zh'?'取消命令':'CANCEL ORDER'}</button></div><p class="review-feedback" role="status"></p></div>`;document.body.append(overlay);
 const close=()=>overlay.remove();overlay.querySelector('[data-review="attack"]').onclick=()=>{close();commit()};overlay.querySelector('[data-review="cancel"]').onclick=close;
 overlay.querySelector('[data-review="scouts"]').onclick=()=>{const out=sendScouts(state,unit.id,destination);if(!out.ok){overlay.querySelector('.review-feedback').textContent=out.reason;return}close();ordering=false;render()};
 overlay.querySelector('[data-review="probe"]').onclick=()=>{const out=probePositions(state,unit.id,destination);if(!out.ok){overlay.querySelector('.review-feedback').textContent=out.reason;return}close();ordering=false;render()};
 overlay.querySelector('[data-review="reinforce"]').onclick=()=>{if(!requestReinforcements(state,unit.id).ok){overlay.querySelector('.review-feedback').textContent=t('recruitFail');return}close();ordering=false;render()};
 overlay.querySelector('[data-review="delay"]').onclick=()=>{const out=delayAttack(state,unit.id,destination);if(!out.ok)return;close();ordering=false;advanceMonth()};
}
