  if(tab==='map')document.querySelector('.inspector .panel-heading').insertAdjacentHTML('afterend',`<label class="theater-picker">${state.grandMap?(lang==='zh'?'领土':'Territory'):t('selectTheater')} <select id="region-choice">${state.regions.map(r=>`<option value="${r.id}" ${r.id===selectedRegion?'selected':''}>${esc(n(r.name))}</option>`).join('')}</select></label><p class="map-group-note">${state.grandMap?(lang==='zh'?'120个可控领土；细线是按古代地点划分的作战近似，并非确证的行政边界。':'120 controllable territories; fine lines are operational approximations based on ancient places, not attested administrative borders.'):t('groupNote')}</p>`);
  if(tab==='map'&&state.grandMap)document.querySelector('.inspector .panel-heading h2').textContent=lang==='zh'?'所选领土':'SELECTED TERRITORY';
  if(tab==='map'&&state.grandMap){const r=region(state,selectedRegion),list=document.querySelector('.inspector .detail-list'),culture=lang==='zh'?({['roman-local']:'意大利与罗马地方文化',['north-african']:'北非地方文化',hellenic:'希腊化地方文化',egypt:'埃及地方文化',parthia:'帕提亚地方文化',armenia:'亚美尼亚地方文化',bosporus:'博斯普鲁斯地方文化',galatia:'加拉太地方文化'}[r?.culture]||r?.culture):r?.culture;if(r&&list)list.insertAdjacentHTML('beforeend',`<div><dt>${lang==='zh'?'地方文化':'Local culture'}</dt><dd>${esc(culture)}</dd></div>`)}
  document.querySelector('#new').textContent=t('menu');
  if(setupOpen)document.querySelector('#app').insertAdjacentHTML('beforeend',`<div class="setup-backdrop"><section class="setup-panel"><button id="close-setup" class="panel-close" aria-label="${t('close')}">×</button><span class="eyebrow">SPQR · XLIX A.C.N.</span><h2>${t('setup')}</h2><div class="setup-saves"><button data-slot="save">${t('save')}</button><button data-slot="load">${t('load')}</button></div><div class="setup-saves"><button id="export-file">${lang==='zh'?'下载存档':'DOWNLOAD SAVE'}</button><button id="import-file">${lang==='zh'?'上传存档':'IMPORT SAVE'}</button><input id="import-input" type="file" accept=".json,application/json" hidden></div><a href="./legacy/">${lang==='zh'?'前往罗马遗产之城':'VISIT LEGACY OF ROME'}</a><p id="setup-faction-note">${chosenFaction==='caesar'||chosenFaction==='senate'?t('warText'):(lang==='zh'?'独立势力以自由模式开始；罗马内战仍由电脑继续演算。目前没有专属胜利条件。':'Independent commands begin in free play while the Roman civil war continues under AI control. A dedicated victory condition is not yet available.')}</p><label>${t('chooseFaction')} <select id="faction-choice">${PLAYABLE.map(id=>`<option value="${id}" ${id===chosenFaction?'selected':''}>${esc(n(FACTIONS[id].name))}</option>`).join('')}</select></label><button id="start-campaign" class="action primary">${t('startCampaign')}</button></section></div>`);
