  if(entryOpen)document.querySelector('#app').insertAdjacentHTML('beforeend',`<div class="entry-screen"><div class="entry-art"></div><div class="entry-vignette"></div><section class="entry-content"><div class="entry-crest">❧　S P Q R　❧</div><p class="entry-era">${lang==='zh'?'公元前四十九年 · 共和国的黄昏':'XLIX BCE · THE REPUBLIC AT DUSK'}</p><h1>${lang==='zh'?'罗马能否得救？':'CAN YOU<br>SAVE ROME?'}</h1><p class="entry-lede">${lang==='zh'?'卢比孔河之后，命运属于你的军团、元老院与人民。':'Beyond the Rubicon, the fate of the Republic belongs to your legions, the Senate, and the people.'}</p><div class="entry-actions"><button id="entry-caesar">${lang==='zh'?'以凯撒开局':'BEGIN AS CAESAR'}</button><button id="entry-senate">${lang==='zh'?'以元老院开局':'BEGIN AS THE SENATE'}</button><label class="entry-foreign-label" for="entry-foreign-choice">${lang==='zh'?'独立势力':'INDEPENDENT COMMAND'}</label><select id="entry-foreign-choice">${PLAYABLE.slice(2).map(id=>`<option value="${id}">${esc(n(FACTIONS[id].name))}</option>`).join('')}</select><button id="entry-foreign">${lang==='zh'?'以所选势力开局':'BEGIN AS SELECTED COMMAND'}</button><button id="entry-continue">${lang==='zh'?'继续当前战役':'CONTINUE CAMPAIGN'}</button><button id="entry-load">${lang==='zh'?'读取存档栏':'LOAD SAVE SLOT'}</button><button id="entry-import">${lang==='zh'?'上传存档文件':'IMPORT SAVE FILE'}</button><button id="entry-export">${lang==='zh'?'下载当前存档':'DOWNLOAD CURRENT SAVE'}</button><a href="./legacy/">${lang==='zh'?'罗马遗产 · 城市中心':'LEGACY OF ROME · CITY HUB'}</a><button id="entry-lang">${lang==='zh'?'ENGLISH':'中文'}</button></div><input id="entry-file" type="file" accept=".json,application/json" hidden><p id="entry-message" role="status"></p><small>${lang==='zh'?'作战领土为基于古代地点的游戏近似，非精确的古代行政区界。':'Operational territories approximate ancient places; their borders are gameplay reconstructions.'}</small></section></div>`);
